--[[\n    🛡️ CYBER APEX V7 ULTIMATE - MOBILE OPTIMIZED EDITION\n    Game: Roblox Murder Mystery 2 (MM2)\n    Optimized for Weak Mobile Devices & Touch Input\n    Features: 4 Tabs (Combat, Visuals, Movement, Utility), Aimbot, Silent Aim,\n    ESP (Roles, Tracers, Distance, Coins, Dropped Gun, Chams), Movement (Speed, Jump, NoClip, Fly, Teleports),\n    Utility (Auto Collect, Anti-AFK, Fullbright, No Fog, Chat Spy, FPS Counter, Player List).\n--]]\n\nlocal Players = game:GetService("Players")\nlocal RunService = game:GetService("RunService")\nlocal UserInputService = game:GetService("UserInputService")\nlocal TweenService = game:GetService("TweenService")\nlocal CoreGui = game:GetService("CoreGui")\nlocal Lighting = game:GetService("Lighting")\nlocal VirtualUser = game:GetService("VirtualUser")\n\nlocal LocalPlayer = Players.LocalPlayer\nlocal Camera = workspace.CurrentCamera\n\n-- Configuration Table\nlocal Config = {\n    -- Combat\n    Aimbot = true,\n    MobileAimActive = true,\n    SmartLogic = true,\n    SilentAim = true,\n    AutoShoot = false,\n    KnifeRangeIndicator = true,\n    FOV = 220,\n    FOVVisible = true,\n    Prediction = 0.048,\n    Smoothing = 0.85,\n    TargetPart = "HumanoidRootPart",\n    \n    -- Visuals\n    ESP = true,\n    ShowRoleName = true,\n    TracerLines = false,\n    DistanceESP = false,\n    CoinESP = true,\n    GunESP = true,\n    BoxESP = false,\n    \n    -- Movement\n    SpeedBoost = false,\n    SpeedValue = 24,\n    JumpPowerBoost = false,\n    JumpValue = 80,\n    NoClip = false,\n    Fly = false,\n    FlySpeed = 50,\n    \n    -- Utility\n    AutoCollect = false,\n    AntiAFK = true,\n    Fullbright = false,\n    NoFog = false,\n    ChatSpy = false,\n    FPSCounter = true,\n    PlayerList = false,\n    \n    UIVisible = true,\n    ActiveTab = "Combat"\n}\n\nif _G.CyberApexInstance then\n    pcall(function() _G.CyberApexInstance:Destroy() end)\nend\n\nlocal ScreenGui = Instance.new("ScreenGui")\nScreenGui.Name = "MM2_CyberApex_V7_Ultimate"\nScreenGui.ResetOnSpawn = false\nScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n_G.CyberApexInstance = ScreenGui\n\npcall(function()\n    if gethui then\n        ScreenGui.Parent = gethui()\n    elseif syn and syn.protect_gui then\n        syn.protect_gui(ScreenGui)\n        ScreenGui.Parent = CoreGui\n    else\n        ScreenGui.Parent = CoreGui\n    end\nend)\nif not ScreenGui.Parent then\n    ScreenGui.Parent = CoreGui\nend\n\n-- Theme Palette (Dark Purple / Indigo)\nlocal Theme = {\n    Background = Color3.fromRGB(15, 15, 22),\n    CardBackground = Color3.fromRGB(22, 22, 32),\n    TabActive = Color3.fromRGB(110, 100, 235),\n    TabInactive = Color3.fromRGB(25, 25, 38),\n    Accent = Color3.fromRGB(120, 110, 245),\n    AccentDim = Color3.fromRGB(90, 80, 200),\n    Text = Color3.fromRGB(220, 220, 235),\n    TextDim = Color3.fromRGB(140, 140, 160),\n    ToggleOn = Color3.fromRGB(90, 110, 220),\n    ToggleOff = Color3.fromRGB(38, 40, 52),\n    CloseBtn = Color3.fromRGB(180, 50, 60)\n}\n\n-- FOV Circle Drawing\nlocal FOVCircle\nif Drawing then\n    pcall(function()\n        FOVCircle = Drawing.new("Circle")\n        FOVCircle.Thickness = 1.5\n        FOVCircle.NumSides = 24 -- Optimized for mobile\n        FOVCircle.Radius = Config.FOV\n        FOVCircle.Filled = false\n        FOVCircle.Visible = Config.FOVVisible\n        FOVCircle.Color = Theme.Accent\n        FOVCircle.Transparency = 0.6\n    end)\nend\n\n-- Main GUI Container\nlocal MainContainer = Instance.new("Frame")\nMainContainer.Name = "MainContainer"\nMainContainer.Size = UDim2.new(0, 310, 0, 460)\nMainContainer.Position = UDim2.new(0.05, 0, 0.12, 0)\nMainContainer.BackgroundColor3 = Theme.Background\nMainContainer.BorderSizePixel = 0\nMainContainer.Active = true\nMainContainer.Draggable = true\nMainContainer.ClipsDescendants = true\nMainContainer.Parent = ScreenGui\n\nInstance.new("UICorner", MainContainer).CornerRadius = UDim.new(0, 12)\n\nlocal MainStroke = Instance.new("UIStroke")\nMainStroke.Color = Theme.Accent\nMainStroke.Thickness = 1.4\nMainStroke.Parent = MainContainer\n\n-- Top Bar\nlocal TopBar = Instance.new("Frame")\nTopBar.Size = UDim2.new(1, 0, 0, 38)\nTopBar.BackgroundTransparency = 1\nTopBar.Parent = MainContainer\n\nlocal Title = Instance.new("TextLabel")\nTitle.Size = UDim2.new(0.6, 0, 1, 0)\nTitle.Position = UDim2.new(0.04, 0, 0, 0)\nTitle.BackgroundTransparency = 1\nTitle.Text = "🛡️ CYBER APEX V7"\nTitle.TextColor3 = Theme.Accent\nTitle.TextSize = 12\nTitle.Font = Enum.Font.GothamBold\nTitle.TextXAlignment = Enum.TextXAlignment.Left\nTitle.Parent = TopBar\n\nlocal CloseBtn = Instance.new("TextButton")\nCloseBtn.Size = UDim2.new(0, 26, 0, 26)\nCloseBtn.Position = UDim2.new(1, -34, 0.5, -13)\nCloseBtn.BackgroundColor3 = Theme.CloseBtn\nCloseBtn.Text = "×"\nCloseBtn.TextColor3 = Color3.new(1,1,1)\nCloseBtn.TextSize = 16\nCloseBtn.Font = Enum.Font.GothamBold\nCloseBtn.Parent = TopBar\nInstance.new("UICorner", CloseBtn).CornerRadius = UDim.new(0, 6)\n\nlocal MinimizeBtn = Instance.new("TextButton")\nMinimizeBtn.Size = UDim2.new(0, 26, 0, 26)\nMinimizeBtn.Position = UDim2.new(1, -66, 0.5, -13)\nMinimizeBtn.BackgroundColor3 = Color3.fromRGB(35, 37, 50)\nMinimizeBtn.Text = "–"\nMinimizeBtn.TextColor3 = Theme.Text\nMinimizeBtn.TextSize = 14\nMinimizeBtn.Font = Enum.Font.GothamBold\nMinimizeBtn.Parent = TopBar\nInstance.new("UICorner", MinimizeBtn).CornerRadius = UDim.new(0, 6)\n\n-- Tab Bar Container (Top Bar for Tabs)\nlocal TabBar = Instance.new("Frame")\nTabBar.Size = UDim2.new(1, -12, 0, 32)\nTabBar.Position = UDim2.new(0, 6, 0, 42)\nTabBar.BackgroundTransparency = 1\nTabBar.Parent = MainContainer\n\nlocal TabLayout = Instance.new("UIListLayout")\nTabLayout.FillDirection = Enum.FillDirection.Horizontal\nTabLayout.SortOrder = Enum.SortOrder.LayoutOrder\nTabLayout.Padding = UDim.new(0, 4)\nTabLayout.Parent = TabBar\n\n-- Content Containers (Scrollable Frames per Tab)\nlocal ContentPages = Instance.new("Folder")\nContentPages.Name = "ContentPages"\nContentPages.Parent = MainContainer\n\nlocal Tabs = {"Combat", "Visuals", "Movement", "Utility"}\nlocal TabFrames = {}\n\nfor i, tabName in ipairs(Tabs) do\n    -- Create Tab Button\n    local tBtn = Instance.new("TextButton")\n    tBtn.Size = UDim2.new(0.24, -3, 1, 0)\n    tBtn.BackgroundColor3 = (tabName == Config.ActiveTab) and Theme.TabActive or Theme.TabInactive\n    tBtn.Text = tabName\n    tBtn.TextColor3 = (tabName == Config.ActiveTab) and Color3.new(1,1,1) or Theme.TextDim\n    tBtn.Font = Enum.Font.GothamBold\n    tBtn.TextSize = 10\n    tBtn.LayoutOrder = i\n    tBtn.Parent = TabBar\n    Instance.new("UICorner", tBtn).CornerRadius = UDim.new(0, 6)\n\n    -- Create Scrolling Frame for Tab\n    local sFrame = Instance.new("ScrollingFrame")\n    sFrame.Name = tabName .. "Frame"\n    sFrame.Size = UDim2.new(1, -12, 1, -84)\n    sFrame.Position = UDim2.new(0, 6, 0, 78)\n    sFrame.BackgroundTransparency = 1\n    sFrame.ScrollBarThickness = 3\n    sFrame.CanvasSize = UDim2.new(0, 0, 0, 520)\n    sFrame.Visible = (tabName == Config.ActiveTab)\n    sFrame.Parent = ContentPages\n\n    local sList = Instance.new("UIListLayout")\n    sList.SortOrder = Enum.SortOrder.LayoutOrder\n    sList.Padding = UDim.new(0, 6)\n    sList.Parent = sFrame\n\n    TabFrames[tabName] = {Button = tBtn, Frame = sFrame}\n\n    tBtn.MouseButton1Click:Connect(function()\n        Config.ActiveTab = tabName\n        for name, data in pairs(TabFrames) do\n            local active = (name == tabName)\n            data.Frame.Visible = active\n            data.Button.BackgroundColor3 = active and Theme.TabActive or Theme.TabInactive\n            data.Button.TextColor3 = active and Color3.new(1,1,1) or Theme.TextDim\n        end\n    end)\nend\n\n-- Floating UI Toggle Button\nlocal FloatUI = Instance.new("Frame")\nFloatUI.Size = UDim2.new(0, 48, 0, 48)\nFloatUI.Position = UDim2.new(0.88, 0, 0.22, 0)\nFloatUI.BackgroundColor3 = Theme.Background\nFloatUI.Active = true\nFloatUI.Draggable = true\nFloatUI.Parent = ScreenGui\nInstance.new("UICorner", FloatUI).CornerRadius = UDim.new(1, 0)\n\nlocal FloatUIStroke = Instance.new("UIStroke")\nFloatUIStroke.Color = Theme.Accent\nFloatUIStroke.Thickness = 1.6\nFloatUIStroke.Parent = FloatUI\n\nlocal FloatUIBtn = Instance.new("TextButton")\nFloatUIBtn.Size = UDim2.new(1,0,1,0)\nFloatUIBtn.BackgroundTransparency = 1\nFloatUIBtn.Text = "UI"\nFloatUIBtn.TextColor3 = Theme.Accent\nFloatUIBtn.TextSize = 12\nFloatUIBtn.Font = Enum.Font.GothamBold\nFloatUIBtn.Parent = FloatUI\n\n-- Floating Mobile Aimbot Activation Button\nlocal FloatAim = Instance.new("Frame")\nFloatAim.Size = UDim2.new(0, 48, 0, 48)\nFloatAim.Position = UDim2.new(0.88, 0, 0.36, 0)\nFloatAim.BackgroundColor3 = Theme.Background\nFloatAim.Active = true\nFloatAim.Draggable = true\nFloatAim.Parent = ScreenGui\nInstance.new("UICorner", FloatAim).CornerRadius = UDim.new(1, 0)\n\nlocal FloatAimStroke = Instance.new("UIStroke")\nFloatAimStroke.Color = Theme.AccentDim\nFloatAimStroke.Thickness = 1.6\nFloatAimStroke.Parent = FloatAim\n\nlocal FloatAimBtn = Instance.new("TextButton")\nFloatAimBtn.Size = UDim2.new(1,0,1,0)\nFloatAimBtn.BackgroundTransparency = 1\nFloatAimBtn.Text = "AIM"\nFloatAimBtn.TextColor3 = Theme.TextDim\nFloatAimBtn.TextSize = 11\nFloatAimBtn.Font = Enum.Font.GothamBold\nFloatAimBtn.Parent = FloatAim\n\n-- UI Element Builders\nlocal function GetTargetScroll(tabName)\n    return TabFrames[tabName] and TabFrames[tabName].Frame\nend\n\nlocal function CreateToggle(tabName, text, default, callback)\n    local parentScroll = GetTargetScroll(tabName)\n    if not parentScroll then return end\n\n    local f = Instance.new("Frame")\n    f.Size = UDim2.new(1, -4, 0, 34)\n    f.BackgroundColor3 = Theme.CardBackground\n    f.Parent = parentScroll\n    Instance.new("UICorner", f).CornerRadius = UDim.new(0, 6)\n\n    local lbl = Instance.new("TextLabel")\n    lbl.Size = UDim2.new(0.62, 0, 1, 0)\n    lbl.Position = UDim2.new(0.04, 0, 0, 0)\n    lbl.BackgroundTransparency = 1\n    lbl.Text = text\n    lbl.TextColor3 = Theme.Text\n    lbl.TextXAlignment = Enum.TextXAlignment.Left\n    lbl.Font = Enum.Font.GothamMedium\n    lbl.TextSize = 11\n    lbl.Parent = f\n\n    local btn = Instance.new("TextButton")\n    btn.Size = UDim2.new(0.28, 0, 0.7, 0)\n    btn.Position = UDim2.new(0.68, 0, 0.15, 0)\n    btn.BackgroundColor3 = default and Theme.ToggleOn or Theme.ToggleOff\n    btn.Text = default and "ON" or "OFF"\n    btn.TextColor3 = Color3.new(1,1,1)\n    btn.Font = Enum.Font.GothamBold\n    btn.TextSize = 10\n    btn.Parent = f\n    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)\n\n    btn.MouseButton1Click:Connect(function()\n        local state = callback()\n        btn.BackgroundColor3 = state and Theme.ToggleOn or Theme.ToggleOff\n        btn.Text = state and "ON" or "OFF"\n    end)\nend\n\nlocal function CreateSelector(tabName, text, options, defaultIndex, callback)\n    local parentScroll = GetTargetScroll(tabName)\n    if not parentScroll then return end\n\n    local f = Instance.new("Frame")\n    f.Size = UDim2.new(1, -4, 0, 34)\n    f.BackgroundColor3 = Theme.CardBackground\n    f.Parent = parentScroll\n    Instance.new("UICorner", f).CornerRadius = UDim.new(0, 6)\n\n    local lbl = Instance.new("TextLabel")\n    lbl.Size = UDim2.new(0.48, 0, 1, 0)\n    lbl.Position = UDim2.new(0.04, 0, 0, 0)\n    lbl.BackgroundTransparency = 1\n    lbl.Text = text\n    lbl.TextColor3 = Theme.Text\n    lbl.TextXAlignment = Enum.TextXAlignment.Left\n    lbl.Font = Enum.Font.GothamMedium\n    lbl.TextSize = 11\n    lbl.Parent = f\n\n    local idx = defaultIndex\n    local btn = Instance.new("TextButton")\n    btn.Size = UDim2.new(0.44, 0, 0.7, 0)\n    btn.Position = UDim2.new(0.52, 0, 0.15, 0)\n    btn.BackgroundColor3 = Color3.fromRGB(28, 28, 40)\n    btn.Text = options[idx]\n    btn.TextColor3 = Theme.Accent\n    btn.Font = Enum.Font.GothamBold\n    btn.TextSize = 10\n    btn.Parent = f\n    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)\n\n    btn.MouseButton1Click:Connect(function()\n        idx = (idx % #options) + 1\n        btn.Text = options[idx]\n        callback(options[idx], idx)\n    end)\nend\n\nlocal function CreateButton(tabName, text, callback)\n    local parentScroll = GetTargetScroll(tabName)\n    if not parentScroll then return end\n\n    local f = Instance.new("Frame")\n    f.Size = UDim2.new(1, -4, 0, 34)\n    f.BackgroundColor3 = Theme.CardBackground\n    f.Parent = parentScroll\n    Instance.new("UICorner", f).CornerRadius = UDim.new(0, 6)\n\n    local btn = Instance.new("TextButton")\n    btn.Size = UDim2.new(0.92, 0, 0.7, 0)\n    btn.Position = UDim2.new(0.04, 0, 0.15, 0)\n    btn.BackgroundColor3 = Theme.AccentDim\n    btn.Text = text\n    btn.TextColor3 = Color3.new(1,1,1)\n    btn.Font = Enum.Font.GothamBold\n    btn.TextSize = 11\n    btn.Parent = f\n    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)\n\n    btn.MouseButton1Click:Connect(function()\n        pcall(callback)\n    end)\nend\n\n-- ==========================================\n-- POPULATE TABS WITH FEATURES\n-- ==========================================\n\n-- TAB 1: Combat (قتال)\nCreateToggle("Combat", "Aimbot (Auto Lock) / تصويب تلقائي", Config.Aimbot, function()\n    Config.Aimbot = not Config.Aimbot\n    return Config.Aimbot\nend)\n\nCreateToggle("Combat", "Silent Aim (MM2) / تصويب صامت", Config.SilentAim, function()\n    Config.SilentAim = not Config.SilentAim\n    return Config.SilentAim\nend)\n\nCreateToggle("Combat", "Smart Logic / منطق ذكي", Config.SmartLogic, function()\n    Config.SmartLogic = not Config.SmartLogic\n    return Config.SmartLogic\nend)\n\nCreateToggle("Combat", "Auto Shoot (Gun) / إطلاق نار تلقائي", Config.AutoShoot, function()\n    Config.AutoShoot = not Config.AutoShoot\n    return Config.AutoShoot\nend)\n\nCreateToggle("Combat", "Knife Range Indicator / مؤشر مدى السكين", Config.KnifeRangeIndicator, function()\n    Config.KnifeRangeIndicator = not Config.KnifeRangeIndicator\n    return Config.KnifeRangeIndicator\nend)\n\nCreateToggle("Combat", "FOV Circle / دائرة المدى", Config.FOVVisible, function()\n    Config.FOVVisible = not Config.FOVVisible\n    if FOVCircle then FOVCircle.Visible = Config.FOVVisible end\n    return Config.FOVVisible\nend)\n\nCreateSelector("Combat", "Target Part / جزء الهدف", {"HumanoidRootPart", "Head"}, 1, function(sel)\n    Config.TargetPart = sel\nend)\n\nCreateSelector("Combat", "Prediction / التنبؤ", {"Low", "Medium", "High"}, 2, function(sel)\n    Config.Prediction = sel == "Low" and 0.025 or sel == "Medium" and 0.048 or 0.072\nend)\n\nCreateSelector("Combat", "Smoothing / النعومة", {"Instant", "Smooth", "Soft"}, 2, function(sel)\n    Config.Smoothing = sel == "Instant" and 1 or sel == "Smooth" and 0.85 or 0.55\nend)\n\n\n-- TAB 2: Visuals (مرئيات)\nCreateToggle("Visuals", "Role ESP (Throttled) / كشف الأدوار", Config.ESP, function()\n    Config.ESP = not Config.ESP\n    return Config.ESP\nend)\n\nCreateToggle("Visuals", "Show Role Name / إظهار اسم الدور", Config.ShowRoleName, function()\n    Config.ShowRoleName = not Config.ShowRoleName\n    return Config.ShowRoleName\nend)\n\nCreateToggle("Visuals", "Tracer Lines / خطوط التتبع", Config.TracerLines, function()\n    Config.TracerLines = not Config.TracerLines\n    return Config.TracerLines\nend)\n\nCreateToggle("Visuals", "Distance ESP / المسافة للهدف", Config.DistanceESP, function()\n    Config.DistanceESP = not Config.DistanceESP\n    return Config.DistanceESP\nend)\n\nCreateToggle("Visuals", "Coin / Gem ESP / كشف العملات والجوهرة", Config.CoinESP, function()\n    Config.CoinESP = not Config.CoinESP\n    return Config.CoinESP\nend)\n\nCreateToggle("Visuals", "Dropped Gun ESP / كشف المسدس الساقط", Config.GunESP, function()\n    Config.GunESP = not Config.GunESP\n    return Config.GunESP\nend)\n\nCreateToggle("Visuals", "Player Chams (Box ESP) / مربعات اللاعبين", Config.BoxESP, function()\n    Config.BoxESP = not Config.BoxESP\n    return Config.BoxESP\nend)\n\n\n-- TAB 3: Movement (حركة)\nCreateToggle("Movement", "Speed Boost / تسريع الحركة", Config.SpeedBoost, function()\n    Config.SpeedBoost = not Config.SpeedBoost\n    return Config.SpeedBoost\nend)\n\nCreateSelector("Movement", "Speed Value / قيمة السرعة", {"20", "24", "32", "40", "50"}, 2, function(sel)\n    Config.SpeedValue = tonumber(sel) or 24\nend)\n\nCreateToggle("Movement", "Jump Power Boost / قوة القفز", Config.JumpPowerBoost, function()\n    Config.JumpPowerBoost = not Config.JumpPowerBoost\n    return Config.JumpPowerBoost\nend)\n\nCreateSelector("Movement", "Jump Value / قيمة القفز", {"60", "80", "100", "120", "150"}, 2, function(sel)\n    Config.JumpValue = tonumber(sel) or 80\nend)\n\nCreateToggle("Movement", "No Clip / المشي عبر الجدران", Config.NoClip, function()\n    Config.NoClip = not Config.NoClip\n    return Config.NoClip\nend)\n\nCreateToggle("Movement", "Fly (Mobile Joystick) / الطيران", Config.Fly, function()\n    Config.Fly = not Config.Fly\n    return Config.Fly\nend)\n\nCreateButton("Movement", "Teleport to Dropped Gun / الانتقال للمسدس", function()\n    for _, obj in ipairs(workspace:GetDescendants()) do\n        if obj.Name == "GunDrop" or obj.Name == "Gun" and obj:IsA("BasePart") then\n            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = obj.CFrame + Vector3.new(0, 3, 0)\n                break\n            end\n        end\n    end\nend)\n\nCreateButton("Movement", "Teleport to Nearest Player / الانتقال لأقرب لاعب", function()\n    local nearest, minDist = nil, math.huge\n    for _, plr in ipairs(Players:GetPlayers()) do\n        if plr ~= LocalPlayer and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then\n            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then\n                local dist = (LocalPlayer.Character.HumanoidRootPart.Position - plr.Character.HumanoidRootPart.Position).Magnitude\n                if dist < minDist then\n                    minDist = dist\n                    nearest = plr\n                end\n            end\n        end\n    end\n    if nearest and nearest.Character and nearest.Character:FindFirstChild("HumanoidRootPart") then\n        LocalPlayer.Character.HumanoidRootPart.CFrame = nearest.Character.HumanoidRootPart.CFrame + Vector3.new(3, 3, 0)\n    end\nend)\n\n\n-- TAB 4: Utility (أدوات)\nCreateToggle("Utility", "Auto Collect Coins / جمع العملات تلقائياً", Config.AutoCollect, function()\n    Config.AutoCollect = not Config.AutoCollect\n    return Config.AutoCollect\nend)\n\nCreateToggle("Utility", "Anti-AFK / منع الطرد للكسل", Config.AntiAFK, function()\n    Config.AntiAFK = not Config.AntiAFK\n    return Config.AntiAFK\nend)\n\nCreateToggle("Utility", "Fullbright / إضاءة كاملة", Config.Fullbright, function()\n    Config.Fullbright = not Config.Fullbright\n    if Config.Fullbright then\n        Lighting.Brightness = 2\n        Lighting.ClockTime = 14\n        Lighting.GlobalShadows = false\n        Lighting.OutdoorAmbient = Color3.fromRGB(150, 150, 150)\n    else\n        Lighting.Brightness = 1\n        Lighting.GlobalShadows = true\n    end\n    return Config.Fullbright\nend)\n\nCreateToggle("Utility", "No Fog / إزالة الضباب", Config.NoFog, function()\n    Config.NoFog = not Config.NoFog\n    if Config.NoFog then\n        Lighting.FogEnd = 999999\n    end\n    return Config.NoFog\nend)\n\nCreateToggle("Utility", "Chat Spy / مراقبة الشات", Config.ChatSpy, function()\n    Config.ChatSpy = not Config.ChatSpy\n    return Config.ChatSpy\nend)\n\nCreateToggle("Utility", "FPS Counter / عداد الإطارات", Config.FPSCounter, function()\n    Config.FPSCounter = not Config.FPSCounter\n    if FPSLabel then FPSLabel.Visible = Config.FPSCounter end\n    return Config.FPSCounter\nend)\n\nCreateToggle("Utility", "Player List Info / قائمة اللاعبين", Config.PlayerList, function()\n    Config.PlayerList = not Config.PlayerList\n    return Config.PlayerList\nend)\n\n\n-- FPS Counter GUI Element\nlocal FPSLabel = Instance.new("TextLabel")\nFPSLabel.Size = UDim2.new(0, 100, 0, 24)\nFPSLabel.Position = UDim2.new(0.05, 0, 0.02, 0)\nFPSLabel.BackgroundTransparency = 0.5\nFPSLabel.BackgroundColor3 = Color3.fromRGB(15, 15, 22)\nFPSLabel.TextColor3 = Color3.fromRGB(100, 255, 150)\nFPSLabel.TextSize = 12\nFPSLabel.Font = Enum.Font.GothamBold\nFPSLabel.Text = "FPS: 60"\nFPSLabel.Visible = Config.FPSCounter\nFPSLabel.Parent = ScreenGui\nInstance.new("UICorner", FPSLabel).CornerRadius = UDim.new(0, 4)\n\n-- UI Visibility Toggles\nlocal function ToggleUI()\n    Config.UIVisible = not Config.UIVisible\n    MainContainer.Visible = Config.UIVisible\n    FloatUIStroke.Color = Config.UIVisible and Theme.Accent or Color3.fromRGB(100, 100, 120)\nend\n\nMinimizeBtn.MouseButton1Click:Connect(ToggleUI)\nFloatUIBtn.MouseButton1Click:Connect(ToggleUI)\n\nFloatAimBtn.MouseButton1Click:Connect(function()\n    Config.MobileAimActive = not Config.MobileAimActive\n    FloatAimStroke.Color = Config.MobileAimActive and Theme.Accent or Theme.AccentDim\n    FloatAimBtn.TextColor3 = Config.MobileAimActive and Theme.Accent or Theme.TextDim\n    FloatAimBtn.Text = Config.MobileAimActive and "AIM+" or "AIM"\nend)\n\nCloseBtn.MouseButton1Click:Connect(function()\n    if FOVCircle then pcall(function() FOVCircle:Remove() end) end\n    ScreenGui:Destroy()\n    _G.CyberApexInstance = nil\nend)\n\n-- Cleanup ESP helper\nlocal function CleanPlayerESP(char)\n    if not char then return end\n    pcall(function()\n        local hl = char:FindFirstChild("ApexESP")\n        if hl then hl:Destroy() end\n        local head = char:FindFirstChild("Head")\n        if head then\n            local bill = head:FindFirstChild("ApexRole")\n            if bill then bill:Destroy() end\n        end\n    end)\nend\n\nPlayers.PlayerRemoving:Connect(function(plr)\n    if plr.Character then\n        CleanPlayerESP(plr.Character)\n    end\nend)\n\n-- Role detection function\nlocal function GetRole(player)\n    if not player or not player.Character then\n        return "Innocent", Color3.fromRGB(100, 200, 150)\n    end\n\n    local char = player.Character\n    local bp = player:FindFirstChild("Backpack")\n\n    if (bp and bp:FindFirstChild("Knife")) or char:FindFirstChild("Knife") then\n        return "Murderer", Color3.fromRGB(235, 65, 85)\n    elseif (bp and bp:FindFirstChild("Gun")) or char:FindFirstChild("Gun") then\n        return "Sheriff", Color3.fromRGB(65, 150, 245)\n    end\n\n    return "Innocent", Color3.fromRGB(100, 200, 150)\nend\n\n-- Get Best Target for Aimbot / Silent Aim\nlocal function GetBestTarget()\n    local myRole = GetRole(LocalPlayer)\n    local best, shortest = nil, Config.FOV\n    local center = Vector2.new(Camera.ViewportSize.X/2, Camera.ViewportSize.Y/2)\n\n    for _, plr in ipairs(Players:GetPlayers()) do\n        if plr ~= LocalPlayer and plr.Character then\n            local char = plr.Character\n            local part = char:FindFirstChild(Config.TargetPart) or char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")\n            local hum = char:FindFirstChildOfClass("Humanoid")\n\n            if part and hum and hum.Health > 0 then\n                local role = GetRole(plr)\n                local valid = true\n\n                if Config.SmartLogic then\n                    if myRole == "Murderer" then\n                        if role == "Murderer" then valid = false end\n                    elseif myRole == "Sheriff" or (myRole == "Innocent" and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Gun")) then\n                        if role ~= "Murderer" then valid = false end\n                    end\n                end\n\n                if valid then\n                    local pos, onScreen = Camera:WorldToViewportPoint(part.Position)\n                    if onScreen then\n                        local dist = (Vector2.new(pos.X, pos.Y) - center).Magnitude\n                        if dist < shortest then\n                            shortest = dist\n                            best = plr\n                        end\n                    end\n                end\n            end\n        end\n    end\n    return best\nend\n\n-- Anti-AFK Connection\nlocal vu = VirtualUser\nLocalPlayer.Idled:Connect(function()\n    if Config.AntiAFK then\n        pcall(function()\n            vu:Button2Down(Vector2.new(0,0), workspace.CurrentCamera.CFrame)\n            task.wait(1)\n            vu:Button2Up(Vector2.new(0,0), workspace.CurrentCamera.CFrame)\n        end)\n    end\nend)\n\n-- Chat Spy implementation\nlocal function SetupChatSpy()\n    pcall(function()\n        for _, plr in ipairs(Players:GetPlayers()) do\n            plr.Chatted:Connect(function(msg)\n                if Config.ChatSpy and plr ~= LocalPlayer then\n                    print("[ChatSpy] [" .. plr.Name .. "]: " .. msg)\n                end\n            end)\n        end\n        Players.PlayerAdded:Connect(function(plr)\n            plr.Chatted:Connect(function(msg)\n                if Config.ChatSpy and plr ~= LocalPlayer then\n                    print("[ChatSpy] [" .. plr.Name .. "]: " .. msg)\n                end\n            end)\n        end\n    end)\nend\nSetupChatSpy()\n\n-- Main Loop with Mobile Throttling for Weak Devices\nlocal lastUpdate = 0\nlocal fpsTick = 0\nlocal frameCount = 0\n\nRunService.RenderStepped:Connect(function(dt)\n    pcall(function()\n        -- FPS Counter Calculation\n        frameCount = frameCount + 1\n        fpsTick = fpsTick + dt\n        if fpsTick >= 1 then\n            if FPSLabel then\n                FPSLabel.Text = "FPS: " .. math.floor(frameCount / fpsTick)\n            end\n            frameCount = 0\n            fpsTick = 0\n        end\n\n        -- FOV Circle update\n        if FOVCircle then\n            FOVCircle.Position = Vector2.new(Camera.ViewportSize.X/2, Camera.ViewportSize.Y/2)\n            FOVCircle.Radius = Config.FOV\n            FOVCircle.Visible = Config.FOVVisible\n        end\n\n        -- Movement: Speed & Jump & NoClip\n        local char = LocalPlayer.Character\n        if char then\n            local hum = char:FindFirstChildOfClass("Humanoid")\n            local hrp = char:FindFirstChild("HumanoidRootPart")\n            \n            if hum then\n                if Config.SpeedBoost then\n                    hum.WalkSpeed = Config.SpeedValue\n                end\n                if Config.JumpPowerBoost then\n                    hum.JumpPower = Config.JumpValue\n                end\n            end\n\n            if Config.NoClip and hrp then\n                for _, part in ipairs(char:GetDescendants()) do\n                    if part:IsA("BasePart") then\n                        part.CanCollide = false\n                    end\n                end\n            end\n        end\n\n        -- Aimbot execution\n        if Config.Aimbot and Config.MobileAimActive then\n            local target = GetBestTarget()\n            if target and target.Character then\n                local part = target.Character:FindFirstChild(Config.TargetPart) or target.Character:FindFirstChild("HumanoidRootPart")\n                if part then\n                    local targetPos = part.Position + (part.AssemblyLinearVelocity or Vector3.zero) * Config.Prediction\n                    local currentCFrame = Camera.CFrame\n                    local goalCFrame = CFrame.new(currentCFrame.Position, targetPos)\n                    Camera.CFrame = currentCFrame:Lerp(goalCFrame, Config.Smoothing)\n                end\n            end\n        end\n\n        -- Auto Shoot logic\n        if Config.AutoShoot then\n            local target = GetBestTarget()\n            if target and target.Character then\n                local myBp = LocalPlayer:FindFirstChild("Backpack")\n                local myChar = LocalPlayer.Character\n                local gun = (myChar and myChar:FindFirstChild("Gun")) or (myBp and myBp:FindFirstChild("Gun"))\n                if gun and gun.Parent == myChar then\n                    pcall(function()\n                        gun:Activate()\n                    end)\n                end\n            end\n        end\n\n        -- Throttle heavy ESP & Coin updates for weak mobile devices (every 0.15 seconds)\n        local now = tick()\n        if now - lastUpdate > 0.15 then\n            lastUpdate = now\n\n            -- ESP & Chams Update\n            for _, plr in ipairs(Players:GetPlayers()) do\n                if plr ~= LocalPlayer and plr.Character then\n                    local pChar = plr.Character\n                    local role, color = GetRole(plr)\n                    local head = pChar:FindFirstChild("Head")\n                    local hum = pChar:FindFirstChildOfClass("Humanoid")\n\n                    if hum and hum.Health > 0 then\n                        -- Highlight / Chams\n                        local hl = pChar:FindFirstChild("ApexESP")\n                        if Config.ESP then\n                            if not hl then\n                                hl = Instance.new("Highlight")\n                                hl.Name = "ApexESP"\n                                hl.Adornee = pChar\n                                hl.Parent = pChar\n                            end\n                            hl.FillColor = color\n                            hl.OutlineColor = Color3.new(1,1,1)\n                            hl.FillTransparency = 0.5\n                        else\n                            if hl then hl:Destroy() end\n                        end\n\n                        -- Billboard Name & Distance ESP\n                        if head then\n                            local bill = head:FindFirstChild("ApexRole")\n                            if Config.ShowRoleName or Config.DistanceESP then\n                                if not bill then\n                                    bill = Instance.new("BillboardGui")\n                                    bill.Name = "ApexRole"\n                                    bill.Size = UDim2.new(0, 120, 0, 50)\n                                    bill.StudsOffset = Vector3.new(0, 2.5, 0)\n                                    bill.AlwaysOnTop = true\n                                    bill.Parent = head\n\n                                    local txt = Instance.new("TextLabel")\n                                    txt.Name = "Text"\n                                    txt.Size = UDim2.new(1, 0, 1, 0)\n                                    txt.BackgroundTransparency = 1\n                                    txt.TextColor3 = color\n                                    txt.TextSize = 12\n                                    txt.Font = Enum.Font.GothamBold\n                                    txt.TextStrokeTransparency = 0.3\n                                    txt.Parent = bill\n                                end\n                                local tLabel = bill:FindFirstChild("Text")\n                                if tLabel then\n                                    local str = ""\n                                    if Config.ShowRoleName then str = plr.Name .. " [" .. role .. "]" end\n                                    if Config.DistanceESP and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then\n                                        local dist = math.floor((LocalPlayer.Character.HumanoidRootPart.Position - head.Position).Magnitude)\n                                        str = str .. "\n(" .. dist .. "m)"\n                                    end\n                                    tLabel.Text = str\n                                    tLabel.TextColor3 = color\n                                end\n                            else\n                                if bill then bill:Destroy() end\n                            end\n                        end\n                    else\n                        CleanPlayerESP(pChar)\n                    end\n                end\n            end\n\n            -- Auto Collect Coins\n            if Config.AutoCollect and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then\n                local hrp = LocalPlayer.Character.HumanoidRootPart\n                for _, obj in ipairs(workspace:GetDescendants()) do\n                    if obj.Name == "Coin_Server" or obj.Name == "Coin" or obj.Name == "Gem" then\n                        if obj:IsA("BasePart") or obj:IsA("Model") then\n                            local part = obj:IsA("Model") and obj.PrimaryPart or obj\n                            if part and (hrp.Position - part.Position).Magnitude < 35 then\n                                pcall(function()\n                                    hrp.CFrame = part.CFrame + Vector3.new(0, 1, 0)\n                                end)\n                            end\n                        end\n                    end\n                end\n            end\n\n        end\n    end)\nend)\n\n-- Silent Aim Remote Interception\nlocal rawmt = getrawmetatable or debug.getrawmetatable\nif rawmt and setreadonly and newcclosure then\n    pcall(function()\n        local mt = rawmt(game)\n        local oldNamecall = mt.__namecall\n        setreadonly(mt, false)\n\n        mt.__namecall = newcclosure(function(self, ...)\n            if checkcaller and checkcaller() then\n                return oldNamecall(self, ...)\n            end\n\n            local method = getnamecallmethod()\n            local args = {...}\n\n            if Config.SilentAim and (method == "FireServer" or method == "InvokeServer") then\n                local name = tostring(self)\n                if name == "KnifeServer" or name == "ShootGun" or name == "Throw" or name == "ThrowKnife" or name == "Shoot" or string.find(name, "Remote") or string.find(name, "Event") then\n                    local target = GetBestTarget()\n                    if target and target.Character then\n                        local part = target.Character:FindFirstChild(Config.TargetPart) or target.Character:FindFirstChild("HumanoidRootPart")\n                        if part then\n                            local vel = part.AssemblyLinearVelocity or Vector3.zero\n                            local pred = part.Position + (vel * Config.Prediction)\n                            for i, v in ipairs(args) do\n                                if typeof(v) == "Vector3" then\n                                    args[i] = pred\n                                elseif typeof(v) == "CFrame" then\n                                    args[i] = CFrame.new(pred)\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n\n            return oldNamecall(self, unpack(args))\n        end)\n        setreadonly(mt, true)\n    end)\nend\n\nprint("🛡️ Cyber Apex V7 Ultimate loaded successfully for MM2 (Mobile Optimized)")\n
